# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_at_least(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _cell_number(table, row_number, column, value):
    """The Decimal in a cell; TabulaError naming the file, the data row (1-based, file order) and the column."""
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%s: row %d: column %r: %r is not a number" % (table.source, row_number, column, value))
    return number


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_at_least(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _parse_key(text):
    """(column, numeric, descending) from COLUMN[:num][:desc]; UsageError when a modifier is wrong."""
    column, *mods = text.split(":")
    numeric = descending = False
    for mod in mods:
        if mod == "num" and not numeric:
            numeric = True
        elif mod == "desc" and not descending:
            descending = True
        else:
            raise UsageError("sort: bad modifier %r in key %r (use :num and :desc, each once)" % (mod, text))
    return column, numeric, descending


def cmd_sort(args, opts):
    _need_at_least(args, 2, "sort FILE KEY...")
    keys = [_parse_key(k) for k in args[1:]]
    table = load(args[0])
    wanted = [(table.index(column), column, numeric, descending) for column, numeric, descending in keys]
    numbered = list(enumerate(table.rows, 1))
    # numeric keys are checked cell by cell, in file order, before anything moves
    numeric_keys = [(at, column) for at, column, numeric, _ in wanted if numeric]
    numbers = {at: {} for at, _ in numeric_keys}
    for n, row in numbered:
        for at, column in numeric_keys:
            numbers[at][n] = _cell_number(table, n, column, row[at])
    for at, column, numeric, descending in reversed(wanted):
        if numeric:
            lookup = numbers[at]
            numbered.sort(key=lambda item: lookup[item[0]], reverse=descending)
        else:
            numbered.sort(key=lambda item: item[1][at], reverse=descending)
    return table.with_rows([row for _, row in numbered])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by one or more columns"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG,
             "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = dict(DEFAULTS), [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # the output could not be written (a full disk, say); the rest of it must not be flushed again at exit
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
# Commands

`tabula [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS...` reads CSV files (UTF-8, an optional byte order mark, LF or CRLF) and prints
a table. Every command returns a `Table`; `--format` says how it is printed (text by default). A mistake in a file or in a
request exits 1 with `tabula: <message>` on standard error; a command line that is not shaped right exits 2.

Each option takes a value, written `--NAME VALUE` or `--NAME=VALUE`, before or after the command. A missing value
(`--kind needs a value`) or one that is not allowed (`--kind must be one of inner, left, got 'x'`) exits 2. `--kind` and
`--keep` are for the commands that need them; every command accepts them.

## show

`tabula show FILE` prints the whole table. Blank lines in the file are ignored. A row with more or fewer fields than the
header is a mistake that names the file and the line (`t.csv: line 3: expected 2 fields, found 1`).

## head

`tabula head FILE N` prints the header and the first N rows. N is a whole number (zero is fine); anything else is a usage
error.

## cols

`tabula cols FILE` prints one row per column with two columns, `position` (from 1) and `column`.

## apply

`tabula apply FILE COLUMN TRANSFORM...` runs each TRANSFORM, left to right, over every value of one column and prints the
whole table. A transform is `name` or `name:ARG`; the list is in `docs/transforms.md`. A value a transform cannot take is
a mistake that names the file and the row (`t.csv: row 2: 'abc' is not a number`). Rows count from 1, the header not
counted.

## sort

`tabula sort FILE KEY...` prints the whole table with its rows sorted by the first KEY, rows that tie by the next KEY, and
so on. A KEY is `COLUMN`, `COLUMN:num`, `COLUMN:desc` or `COLUMN:num:desc` (the modifiers in either order). Without `:num`
the cells compare as text, by code point, so `B` comes before `a`; with `:num` they compare as decimal numbers, exactly, so
`9.5` comes before `10` and `10` ties with `10.00`. `:desc` reverses that key only. Rows that tie on every key stay in the
order of the file, also with `:desc`.

With `:num`, every cell of that column has to be a number, and the check is done before any row moves: the first cell that
is not one is a mistake that names the file, the row and the column (`t.csv: row 3: column 'price': 'abc' is not a
number`). Rows count from 1 in the order of the file, the header not counted. A column the file does not have is a mistake
too (`t.csv: no column 'x' (columns: name, price)`).

A command line that is not shaped right exits 2 before the file is read: no KEY (`usage: tabula sort FILE KEY...`), or a
modifier that is not `num` or `desc`, empty, or given twice (`sort: bad modifier 'x' in key 'price:x' (use :num and :desc,
each once)`).
"""Tests for `tabula sort` and the shared --kind / --keep options, all through `python -m tabula`."""
import contextlib, io, os, subprocess, sys, tempfile, unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))

from tabula import engine

PEOPLE = 'name,city,price\nbob,Oslo,10\nAnn,Rome,9.5\nbob,Bonn,10.00\nCy,Oslo,-2\nann,Rome,100\n'
TIES = 'k,n\na,1\nb,2\na,3\nb,4\na,5\n'


class SortTests(unittest.TestCase):
    def run_cli(self, *argv, files=None):
        with tempfile.TemporaryDirectory() as d:
            for k, v in (files or {}).items():
                with open(os.path.join(d, k), 'w', encoding='utf-8', newline='') as fh:
                    fh.write(v)
            env = dict(os.environ, PYTHONPATH=os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
            p = subprocess.run([sys.executable, '-m', 'tabula'] + list(argv), cwd=d, env=env,
                               capture_output=True, text=True)
            return p.returncode, p.stdout, p.stderr

    def check(self, argv, rc, out, err=None, files=None):
        got_rc, got_out, got_err = self.run_cli(*argv, files=files or {'t.csv': PEOPLE})
        self.assertEqual((got_rc, got_out), (rc, out), got_err)
        self.assertEqual(bool(got_err), rc != 0)
        if err is not None:
            self.assertEqual(got_err, 'tabula: %s\n' % err)

    def test_orders(self):
        cases = [
            (('sort', 't.csv', 'name'), 'name  city  price\nAnn   Rome  9.5\nCy    Oslo  -2\nann   Rome  100\n'
                                        'bob   Oslo  10\nbob   Bonn  10.00\n'),
            (('sort', 't.csv', 'name:desc'), 'name  city  price\nbob   Oslo  10\nbob   Bonn  10.00\nann   Rome  100\n'
                                             'Cy    Oslo  -2\nAnn   Rome  9.5\n'),
            (('sort', 't.csv', 'price'), 'name  city  price\nCy    Oslo  -2\nbob   Oslo  10\n'
                                         'bob   Bonn  10.00\nann   Rome  100\nAnn   Rome  9.5\n'),
            (('sort', 't.csv', 'price:num'), 'name  city  price\nCy    Oslo  -2\nAnn   Rome  9.5\nbob   Oslo  10\n'
                                             'bob   Bonn  10.00\nann   Rome  100\n'),
            (('sort', 't.csv', 'price:desc:num'), 'name  city  price\nann   Rome  100\nbob   Oslo  10\n'
                                                  'bob   Bonn  10.00\nAnn   Rome  9.5\nCy    Oslo  -2\n'),
            (('sort', 't.csv', 'price:num:desc'), 'name  city  price\nann   Rome  100\nbob   Oslo  10\n'
                                                  'bob   Bonn  10.00\nAnn   Rome  9.5\nCy    Oslo  -2\n'),
            (('sort', 't.csv', 'name', 'city'), 'name  city  price\nAnn   Rome  9.5\nCy    Oslo  -2\nann   Rome  100\n'
                                                'bob   Bonn  10.00\nbob   Oslo  10\n'),
            (('sort', 't.csv', 'name', 'price:num:desc'),
             'name  city  price\nAnn   Rome  9.5\nCy    Oslo  -2\nann   Rome  100\nbob   Oslo  10\nbob   Bonn  10.00\n'),
            (('sort', 't.csv', 'name:desc', 'city'), 'name  city  price\nbob   Bonn  10.00\nbob   Oslo  10\n'
                                                     'ann   Rome  100\nCy    Oslo  -2\nAnn   Rome  9.5\n'),
        ]
        for argv, out in cases:
            with self.subTest(argv=argv):
                self.check(argv, 0, out)

    def test_ties_keep_file_order(self):
        files = {'t.csv': TIES}
        self.check(('sort', 't.csv', 'k'), 0, 'k  n\na  1\na  3\na  5\nb  2\nb  4\n', files=files)
        self.check(('sort', 't.csv', 'k:desc'), 0, 'k  n\nb  2\nb  4\na  1\na  3\na  5\n', files=files)
        self.check(('sort', 't.csv', 'n:num:desc', 'k'), 0, 'k  n\na  5\nb  4\na  3\nb  2\na  1\n', files=files)

